add_filter( 'woocommerce_loop_product_link', 'perfectpixel_custom_product_links_in_loop', 10, 2 );

function perfectpixel_custom_product_links_in_loop( $link, $product ) {
	foreach ( explode( '|', '{{loop_custom_links}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && (int) $parts[0] === (int) $product->get_id() && '' !== $parts[1] ) {
			return 0 === strpos( $parts[1], '/' ) ? home_url( $parts[1] ) : esc_url_raw( $parts[1] );
		}
	}
	return $link;
}
